CREATE TABLE test_stability_snapshots (id UUID PRIMARY KEY,stable_test_id CHAR(64) NOT NULL,stability_class VARCHAR(32) NOT NULL,classifier_version VARCHAR(32) NOT NULL,total_executions INTEGER NOT NULL,pass_count INTEGER NOT NULL,failure_count INTEGER NOT NULL,error_count INTEGER NOT NULL,fail_to_pass_reruns INTEGER NOT NULL,unique_failure_fingerprints INTEGER NOT NULL,computed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT uq_stability_snapshot UNIQUE(stable_test_id,classifier_version));
CREATE INDEX idx_test_cases_fingerprint ON test_case_executions(failure_fingerprint); CREATE INDEX idx_stability_class ON test_stability_snapshots(stability_class);
